import {defaults,cleanList,moveUnit,formFor,encodeList,decodeList} from './tierlist-model.mjs';
import {drawTierlist} from './tierlist-render.mjs';
import {saveTierlist,readTierlist} from './tierlist-api.mjs';
import {searchMatches} from './tatari-model.mjs';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n},key='tatari-tierlist-v1';let state=defaults(),units=[],selected=null,dragged=null,recordId=null,revision=null;
const status=s=>$('maker-status').textContent=s;
function persist(){try{localStorage.setItem(key,JSON.stringify(state));status('Saved in this browser.')}catch{status('Browser storage unavailable. Use a share link to keep your list.')}}
function tile(id){const unit=units.find(u=>u.id===id),f=formFor(unit,state.tier),n=el('button',undefined,'tatari-tile'),img=el('img');n.type='button';n.draggable=true;n.dataset.id=id;const name=typeof f.name==='string'?f.name:f.name.en||f.name.zh;img.src=new URL('./tatari-data/'+f.playerhead,import.meta.url);img.alt='';img.loading='lazy';img.draggable=false;n.append(img,el('span',name));n.setAttribute('aria-label',name+' · tier '+f.evolution);n.title=name+' · tier '+f.evolution;n.setAttribute('aria-pressed',String(selected===id));n.onclick=e=>{e.stopPropagation();selected=selected===id?null:id;render();status(selected===null?'Selection cleared.':name+' selected. Choose a ranking row or return to pool.')};n.ondragstart=e=>{dragged=id;e.dataTransfer.setData('text/plain',String(id));e.dataTransfer.effectAllowed='move'};n.ondragend=()=>{dragged=null;document.querySelectorAll('.drop-over').forEach(n=>n.classList.remove('drop-over'))};return n}
function place(id,index){if(!units.some(u=>u.id===id))return;moveUnit(state,id,index);selected=null;persist();render()}
function render(){const board=$('rank-board');board.replaceChildren();for(const [index,row] of state.rows.entries()){const section=el('div',undefined,'tier-row'),label=el('div',undefined,'tier-label'),input=el('input'),color=el('input'),items=el('div',undefined,'rank-items');label.style.background=row.color;label.append(el('strong',row.label));const controls=el('div',undefined,'tier-row-controls'),settings=el('button',undefined,'row-settings'),gear=el('span','⚙'),arrows=el('div',undefined,'row-arrows');gear.setAttribute('aria-hidden','true');settings.type='button';settings.setAttribute('aria-label','Settings for row '+(index+1));settings.append(gear);settings.onclick=()=>openSettings(index);for(const [direction,icon] of [[-1,''],[1,'']]){const b=el('button',icon);b.type='button';b.className=direction<0?'row-up':'row-down';b.setAttribute('aria-label','Move row '+(index+1)+(direction<0?' up':' down'));b.disabled=index+direction<0||index+direction>=state.rows.length;b.onclick=()=>{const target=index+direction;[state.rows[index],state.rows[target]]=[state.rows[target],state.rows[index]];persist();render();$('rank-board').children[target].querySelector('.row-settings').focus()};arrows.append(b)}controls.append(settings,arrows);items.tabIndex=0;items.setAttribute('role','group');items.setAttribute('aria-label','Place selected Tatari in row '+(index+1));items.onclick=()=>{if(selected!==null)place(selected,index)};items.onkeydown=e=>{if(e.target===items&&['Enter',' '].includes(e.key)){e.preventDefault();if(selected!==null)place(selected,index)}};items.ondragover=e=>{if(dragged!==null){e.preventDefault();section.classList.add('drop-over')}};items.ondragleave=()=>section.classList.remove('drop-over');items.ondrop=e=>{e.preventDefault();section.classList.remove('drop-over');if(dragged!==null)place(dragged,index)};items.append(...row.units.map(tile));section.append(label,items,controls);board.append(section)}const ranked=new Set(state.rows.flatMap(r=>r.units)),pool=$('tatari-pool');pool.replaceChildren(...units.filter(u=>!ranked.has(u.id)&&searchMatches(u,$('pool-search').value)).map(u=>tile(u.id)));if(!pool.children.length)pool.append(el('p',ranked.size===units.length?'All Tatari ranked.':'No Tatari matches this search.'));$('return-pool').hidden=selected===null;pool.ondragover=e=>{if(dragged!==null)e.preventDefault()};pool.ondrop=e=>{e.preventDefault();if(dragged!==null)place(dragged,-1)}}

const rowDialog=el('dialog',undefined,'row-settings-dialog');rowDialog.setAttribute('aria-labelledby','row-settings-title');document.body.append(rowDialog);
function openSettings(index){const row=state.rows[index],header=el('div',undefined,'modal-head'),heading=el('h3','Row settings'),close=el('button','×','btn secondary'),body=el('div',undefined,'modal-body'),label=el('label','Label text'),input=el('input'),palette=el('div',undefined,'row-color-palette'),colorLabel=el('label','Custom color'),color=el('input'),actions=el('div',undefined,'row-settings-actions');heading.id='row-settings-title';close.type='button';close.setAttribute('aria-label','Close row settings');close.onclick=()=>rowDialog.close();input.value=row.label;input.maxLength=16;input.oninput=()=>{row.label=input.value.trim()||'?';persist();render()};label.append(input);const updateColor=value=>{row.color=value;color.value=value;palette.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===value)));persist();render()};for(const value of ['#ff7f7f','#ffbf7f','#ffdf7f','#ffff7f','#bfff7f','#7fff7f','#7fffff','#7fbfff','#7f7fff','#ff7fff','#bf7fbf','#333333','#888888','#cccccc','#ffffff']){const b=el('button');b.type='button';b.style.background=value;b.dataset.color=value;b.setAttribute('aria-label','Use color '+value);b.setAttribute('aria-pressed',String(row.color===value));b.onclick=()=>updateColor(value);palette.append(b)}color.type='color';color.value=row.color;color.oninput=()=>updateColor(color.value);colorLabel.append(color);for(const [name,action] of [['Delete row',()=>{state.rows.splice(index,1)}],['Clear row Tatari',()=>{row.units=[]}],['Add row above',()=>{state.rows.splice(index,0,{label:'New',color:row.color,units:[]})}],['Add row below',()=>{state.rows.splice(index+1,0,{label:'New',color:row.color,units:[]})}]]){const b=el('button',name,'btn secondary');b.type='button';b.disabled=name==='Delete row'?state.rows.length===1:name.startsWith('Add')&&state.rows.length>=20;b.onclick=()=>{action();selected=null;persist();render();rowDialog.close();$('rank-board').children[Math.min(index,state.rows.length-1)].querySelector('.row-settings').focus()};actions.append(b)}header.append(heading,close);body.append(el('p','Label background color'),palette,label,colorLabel,actions,el('p','Clearing or deleting a row returns its Tatari to the unranked pool.'));rowDialog.replaceChildren(header,body);rowDialog.showModal();input.focus()}
function fill(){const old=['#ff9c95','#ffc68b','#ffe17a','#bce594','#a7d9f3'],standard=['#ff7f7f','#ffbf7f','#ffdf7f','#ffff7f','#bfff7f'];state.rows.forEach(r=>{const i=old.indexOf(r.color);if(i>=0)r.color=standard[i]}); $('list-title').value=state.title;$('list-mode').value=state.gameMode;$('list-tier').value=state.tier;$('list-notes').value=state.notes;render()}
for(const [id,field] of [['list-title','title'],['list-mode','gameMode'],['list-tier','tier'],['list-notes','notes']])$(id).oninput=()=>{state[field]=field==='tier'?Number($(id).value):$(id).value;persist();if(field==='tier')render()};$('pool-search').oninput=render;$('return-pool').onclick=()=>{if(selected!==null)place(selected,-1)};
$('reset').onclick=()=>{if(!confirm('Start a new tierlist? Your current browser copy will be replaced.'))return;state=defaults();recordId=revision=null;selected=null;history.replaceState(null,'',location.pathname);persist();fill()};
$('share').onclick=async()=>{try{const url=new URL(location.href);url.search='';url.hash='list='+encodeList(state);await navigator.clipboard.writeText(url.href);status('Share link copied.')}catch{status('Could not copy the link. Check clipboard permission and try again.')}};
$('export').onclick=async()=>{const button=$('export');button.disabled=true;try{const canvas=await drawTierlist(document.createElement('canvas'),state,units),blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error('Image export failed.');const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=(state.title||'tierlist').replace(/[^a-z0-9_-]/gi,'-')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Image exported.')}catch(e){status(e.message)}finally{button.disabled=false}};
async function save(publish){const buttons=[$('save'),$('publish')];buttons.forEach(b=>b.disabled=true);try{if(!state.title.trim())throw Error('Give your tierlist a title first.');const r=await saveTierlist(recordId,revision,state,publish);recordId=r.id;revision=r.revision;const url=new URL(location.href);url.hash='';url.search='';url.searchParams.set('tierlist',recordId);url.searchParams.set('private','1');history.replaceState(null,'',url);status(publish?'Published to Community tierlist.':'Account draft saved.')}catch(e){status(e.message)}finally{buttons.forEach(b=>b.disabled=false)}}$('save').onclick=()=>save(false);$('publish').onclick=()=>save(true);
try{const response=await fetch(new URL('./tatari-data/roster.json',import.meta.url));if(!response.ok)throw Error('Could not load Tatari.');units=(await response.json()).units.sort((a,b)=>a.id-b.id);const params=new URL(location.href).searchParams;if(location.hash.startsWith('#list=')){state=cleanList(decodeList(location.hash.slice(6)),units);status('Shared tierlist opened.')}else if(params.has('tierlist')){const own=params.get('private')==='1',r=await readTierlist(params.get('tierlist'),own);state=cleanList(r.payload,units);if(own){recordId=r.id;revision=r.revision}status(own?'Account draft opened.':'Community tierlist opened as a new draft.')}else{try{const raw=localStorage.getItem(key);if(raw)state=cleanList(JSON.parse(raw),units)}catch{}status('Ready. Changes are saved in this browser.')}fill()}catch(e){status(e.message);[$('save'),$('publish'),$('export'),$('share')].forEach(b=>b.disabled=true)}
